// ?token=<report_id>&decision=approve|reject&edit=...&reason=...
// approve(+edit) -> approved 확정 / reject -> rejected. 결과 HTML 반환.
const SB_URL = $env.SUPABASE_URL;
const SB_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
// Code-node sandbox has no fetch/$helpers/process (task-runner vm).
// Outbound HTTPS via allowlisted require('https') (NODE_FUNCTION_ALLOW_BUILTIN=https).
const https = require('https');
function splitUrl(url) {
  const m = url.match(/^https:\/\/([^/]+)(\/[\s\S]*)?$/);
  if (!m) throw new Error('bad url');
  return { host: m[1], path: m[2] || '/' };
}
function httpRaw(method, url, headers, bodyStr, timeoutMs) {
  const u = splitUrl(url);
  return new Promise((resolve, reject) => {
    const req = https.request({ method, hostname: u.host, path: u.path, headers: headers || {} }, (res) => {
      let data = '';
      res.setEncoding('utf8');
      res.on('data', (c) => { data += c; });
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });
    req.on('error', reject);
    req.setTimeout(timeoutMs || 25000, () => { req.destroy(new Error('timeout')); });
    if (bodyStr !== undefined) req.write(bodyStr);
    req.end();
  });
}
async function httpGet(url, timeoutMs) { const r = await httpRaw('GET', url, {}, undefined, timeoutMs); return r.body; }
async function httpJson(method, url, headers, bodyObj, timeoutMs) {
  const r = await httpRaw(method, url, headers, bodyObj === undefined ? undefined : JSON.stringify(bodyObj), timeoutMs);
  if (r.status >= 400) throw new Error('HTTP' + r.status + ' ' + String(r.body).slice(0, 200));
  return r.body ? JSON.parse(r.body) : null;
}
async function sb(method, path, body) {
  return httpJson(method, SB_URL + '/rest/v1/' + path,
    { apikey: SB_KEY, Authorization: 'Bearer ' + SB_KEY, 'Content-Type': 'application/json', Prefer: 'return=representation' },
    body || undefined, 15000);
}
function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>');
}
const out = [];
for (const it of $input.all()) {
  const q = it.json.query || {};
  const rid = parseInt(q.token, 10);
  const decision = String(q.decision || '');
  const edit = String(q.edit || '').slice(0, 500);
  const reason = String(q.reason || '').slice(0, 500);
  let html = '';
  if (!rid || (decision !== 'approve' && decision !== 'reject')) {
    html = '<h2>잘못된 승인 링크</h2><p>token과 decision(approve|reject)이 필요합니다.</p>';
  } else {
    const rows = await sb('GET', 'agent_reports?id=eq.' + rid + '&select=id,draft,status');
    const rep = Array.isArray(rows) ? rows[0] : rows;
    if (!rep) {
      html = '<h2>리포트 없음</h2><p>id=' + rid + ' 없음.</p>';
    } else if (rep.status !== 'pending') {
      html = '<h2>이미 처리됨</h2><p>상태=' + esc(rep.status) + '</p>';
    } else if (decision === 'approve') {
      const final = edit ? rep.draft + '\n\n[승인자 수정]\n' + edit : rep.draft;
      await sb('PATCH', 'agent_reports?id=eq.' + rid, { status: 'approved', final });
      await sb('POST', 'agent_runs', { scenario: 'approval', ms: 0, prompt_tokens: 0, completion_tokens: 0, cost_krw: 0, status: 'approved', note: 'report=' + rid });
      html = '<h2>확정됨</h2><p>' + esc(final) + '</p>';
    } else {
      await sb('PATCH', 'agent_reports?id=eq.' + rid, { status: 'rejected', final: reason || '사유 없음' });
      await sb('POST', 'agent_runs', { scenario: 'approval', ms: 0, prompt_tokens: 0, completion_tokens: 0, cost_krw: 0, status: 'rejected', note: 'report=' + rid });
      html = '<h2>거절됨</h2><p>' + esc(reason || '사유 없음') + '</p>';
    }
  }
  out.push({ json: { html: '<html><head><meta charset="utf-8"></head><body>' + html + '</body></html>' } });
}
return out;
